package com.apple.spark.core;

import static org.junit.jupiter.api.Assertions.*;

import javax.ws.rs.WebApplicationException;
import javax.ws.rs.core.Response;
import java.lang.reflect.Method;

import org.junit.jupiter.api.Test;

public class ApplicationSubmissionHelperTest {

  @Test
  public void testParseJsonValid_shouldReturnRequestObject() {
    String json = "{}";
    SubmitApplicationRequest req = ApplicationSubmissionHelper.parseSubmitRequest(json, "application/json");
    assertNotNull(req, "Parsed request should not be null for empty JSON object");
  }

  @Test
  public void testParseYamlValid_shouldReturnRequestObject() {
    String yaml = "key: value";
    SubmitApplicationRequest req = ApplicationSubmissionHelper.parseSubmitRequest(yaml, "application/x-yaml");
    assertNotNull(req, "Parsed request should not be null for simple YAML");
  }

  @Test
  public void testParseJsonInvalid_whenLooksLikeFilePath_shouldThrowBadRequestWithFilePathMessage() {
    String filePathLike = "/tmp/some-file.txt";
    WebApplicationException ex =
        assertThrows(
            WebApplicationException.class,
            () -> ApplicationSubmissionHelper.parseSubmitRequest(filePathLike, "application/json"));
    Response resp = ex.getResponse();
    assertNotNull(resp);
    assertEquals(400, resp.getStatus());
    String msg = ex.getMessage();
    assertNotNull(msg);
    assertTrue(
        msg.contains("looks like a file path") || msg.contains("Invalid request body"),
        "Expected message to indicate the request body looked like a file path. Actual: " + msg);
  }

  @Test
  public void testParseJsonInvalid_whenNotFilePath_shouldThrowBadRequestWithJsonError() {
    String invalidJson = "this is not json";
    WebApplicationException ex =
        assertThrows(
            WebApplicationException.class,
            () -> ApplicationSubmissionHelper.parseSubmitRequest(invalidJson, null));
    Response resp = ex.getResponse();
    assertNotNull(resp);
    assertEquals(400, resp.getStatus());
    String msg = ex.getMessage();
    assertNotNull(msg);
    assertTrue(msg.contains("Invalid JSON request"), "Expected Invalid JSON request message. Actual: " + msg);
  }

  @Test
  public void testParseYamlInvalid_shouldThrowBadRequestWithYamlError() {
    // malformed YAML that will cause parser to throw
    String badYaml = ":\n -";
    WebApplicationException ex =
        assertThrows(
            WebApplicationException.class,
            () -> ApplicationSubmissionHelper.parseSubmitRequest(badYaml, "text/yaml"));
    Response resp = ex.getResponse();
    assertNotNull(resp);
    assertEquals(400, resp.getStatus());
    String msg = ex.getMessage();
    assertNotNull(msg);
    assertTrue(msg.contains("Invalid YAML request"), "Expected Invalid YAML request message. Actual: " + msg);
  }

  @Test
  public void testLooksLikeFilePath_reflectionInvocation() throws Exception {
    // invoke looksLikeFilePath via reflection (as requested)
    Method m = ApplicationSubmissionHelper.class.getDeclaredMethod("looksLikeFilePath", String.class);
    m.setAccessible(true);

    Boolean result1 = (Boolean) m.invoke(null, "/etc/passwd");
    assertTrue(result1, "/etc/passwd should look like a file path");

    Boolean result2 = (Boolean) m.invoke(null, "not/a/path?");
    assertFalse(result2, "String 'not/a/path?' should not match file path pattern");

    Boolean result3 = (Boolean) m.invoke(null, "~/.bashrc");
    assertTrue(result3, "~/.bashrc should look like a file path");
  }
}

